echo "4/7 Lettore di pagine web (servizio giot-fetch, riservato a chi ha fatto l'accesso)"
FDIR="${FDIR:-/opt/giot-fetch}"
FDATA="${FDATA:-/opt/giot-fetch-data}"
KDIR="${KDIR:-/opt/giot-fetch-key}"   # chiave di cifratura dell'archivio clienti: cartella SEPARATA dai dati
FETCH_MODE="${FETCH_MODE:-auto}"
FETCH_UP=0; APPS_UP=0
fetch_health() {
  local i
  for i in $(seq 1 45); do
    [ "$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3002/health || true)" = 200 ] && return 0
    sleep 1
  done
  return 1
}
